#!/usr/bin/env bash
# Installe le hook pre-push de garde de confidentialité.
set -euo pipefail

MARKER="# GENERATED BY agentic-cockpit install-hooks.sh"

COMMON_DIR="$(git rev-parse --git-common-dir)"
HOOKS_DIR="${COMMON_DIR}/hooks"
HOOK_PATH="${HOOKS_DIR}/pre-push"

mkdir -p "${HOOKS_DIR}"

if [ -e "${HOOK_PATH}" ]; then
    if ! grep -qF "${MARKER}" "${HOOK_PATH}" 2>/dev/null; then
        echo "Erreur : un hook pre-push non généré par install-hooks.sh existe déjà (${HOOK_PATH})." >&2
        exit 1
    fi
fi

cat > "${HOOK_PATH}" <<'EOF'
#!/usr/bin/env bash
# GENERATED BY agentic-cockpit install-hooks.sh
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"

while read -r local_ref local_sha remote_ref remote_sha; do
    [ -z "${local_sha:-}" ] && continue
    python3 "${REPO_ROOT}/scripts/privacy-check.py" --repo "${REPO_ROOT}" --range "${remote_sha}..${local_sha}"
done
EOF

chmod +x "${HOOK_PATH}"
